// Checks the generated src/data/d2x against the Diablo II semantics the game will rely on, from the
// outside: it reads the generated files the way the game will, and the source tables, and works each
// expectation out again instead of trusting the importer's own checks.
//
//   node tools/d2-import.mjs && node tools/d2-validate.mjs
//
// Prints the counts left after the scope filters, then one line per check and any warnings; exits 1
// if a check fails (warnings never fail it).
// What it holds the data to:
// - the scope: no Warlock-era row, none ladder-only both now and in D2R 2.7 (the last tables before
//   the Warlock expansion), and every row as 2.7 has it, for the values the game reads;
// - the names: every unique, set and runeword in scope is named or listed in tools/d2-names/report.md,
//   no official proper noun anywhere, runes "N 号符文";
// - the names against the official ones (tools/d2-names/style.md, style-en.md, hard rule 1): none
//   is its row's official Chinese with only 的 or 之 changed, nor Blizzard's English with only small
//   words or the order changed; a warning, not a failure, for an English one a letter or two from
//   Blizzard's (a homophone, and whether a veteran knows a name at a glance, are for a person);
// - the English names (tools/d2-names/style-en.md): every renamed row has one, plain ASCII in Title
//   Case, the glossary's forms, no two alike, hirelings three letters apart and no three of them
//   with one ending;
// - the units: charstats quarters, monster stats as monlvl percentages through D2MOO's ApplyRatio,
//   the expansion columns, HitShift, manashift and frames in skills;
// - the drops: Andariel's and the Countess' items per kill against d2data's tcprecalc, worked out
//   and simulated;
// - the properties: every code is one src/items/props.ts reads or KNOWN_UNMAPPED lists;
// - the skills: all 30 Paladin and 30 Sorceress skills.
//
// D2MOO references are to github.com/ThePhrozenKeep/D2MOO at commit d9d394f, by file and line.
import fs from 'node:fs';
import path from 'node:path';
import { DATA, REF27, ROOT, importTs, load, rows, strings } from './d2/load.mjs';
import { KNOWN_UNMAPPED, SKILL_PROPS } from './d2/props.mjs';
import { OUT_OF_SCOPE_TC, WARLOCK, WARLOCK_SETS, WARLOCK_TYPES, isWarlockTab, ladderOnly, latestSeason } from './d2/scope.mjs';
import { leaves, leavesPre, maxDiff, seeded, simulate } from './d2/validate.mjs';

// ───────────────────────── the data ─────────────────────────
const D2X = path.join(ROOT, 'src/data/d2x');
const HEAD = '// Generated by tools/d2-import.mjs';
const X = {};
const files = fs.readdirSync(D2X).filter((f) => f.endsWith('.ts')).sort();
for (const f of files) if (f !== 'types.ts') Object.assign(X, await importTs(`src/data/d2x/${f}`));
const { PROP_CODES } = await importTs('src/items/props.ts');
const [uniqueJ, setItemsJ, setsJ, runesJ, skillsJ, monJ, lvlJ] = await Promise.all(
  ['uniqueitems', 'setitems', 'sets', 'runes', 'skills', 'monstats', 'monlvl'].map((n) => load(DATA, n)),
);
const R27 = Object.fromEntries(
  await Promise.all(
    [
      'weapons', 'armor', 'misc', 'uniqueitems', 'setitems', 'sets', 'runes', 'magicprefix', 'magicsuffix', 'automagic', 'gems', 'charstats', 'playerclass',
      'difficultylevels', 'itemratio', 'npc', 'gamble', 'hireling', 'levels', 'monstats', 'monlvl', 'monprop', 'superuniques', 'skills', 'tcprecalc',
      'books', 'itemstatcost',
    ].map(async (n) => [n, await load(REF27, n)]),
  ),
);
const S = await strings('item-names', 'item-runes', 'item-nameaffixes');
const report = fs.readFileSync(path.join(ROOT, 'tools/d2-names/report.md'), 'utf8');

// ───────────────────────── the checks ─────────────────────────
let failed = 0;
let passed = 0;
/** one check: `bad` lists what fails it (empty: it holds); the first few are shown */
function check(label, bad) {
  const list = Array.isArray(bad) ? bad : bad ? [String(bad)] : [];
  if (!list.length) {
    passed++;
    console.log(`  ok    ${label}`);
    return;
  }
  failed++;
  const shown = list.slice(0, 12).map((x) => `          ${x}`);
  if (list.length > 12) shown.push(`          … ${list.length - 12} more`);
  console.log(`  FAIL  ${label}: ${list.length}\n${shown.join('\n')}`);
}
let warned = 0;
/** a warning: printed in full for a person to look at, never failing the run; counted by name listed */
function warn(label, list) {
  if (!list.length) return;
  warned += list.length;
  console.log(`  warn  ${label}: ${list.length}\n${list.map((x) => `          ${x}`).join('\n')}`);
}
const section = (s) => console.log(`\n${s}`);
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);
const by = (t, key) => new Map(rows(t).filter((r) => r[key] !== undefined).map((r) => [r[key], r]));
/** records a field whose generated value is not the expected one */
const mismatch = (out, where, field, want, got) => {
  if (!same(want, got)) out.push(`${where} ${field}: ${JSON.stringify(got)}, expected ${JSON.stringify(want)}`);
};
/** a column's value as the generated data keeps an optional one: absent when 0 or empty */
const opt = (v) => (v ? v : undefined);
const numbered = (r, n, col) => [...Array(n)].map((_, i) => r[col(i + 1)]).filter((v) => v !== undefined && v !== '');
/** item type columns: a type ItemTypes.txt lacks matches nothing (the Sorceress' skill-tab prefixes name a "staff" for staf) */
const itypes = (r, n) => numbered(r, n, (i) => `itype${i}`).filter((c) => X.D2X_ITEM_TYPES[c]);

const W = X.D2X_WEAPONS;
const A = X.D2X_ARMOR;
const M = X.D2X_MISC;
const BASES = [...W, ...A, ...M];
const BASE = new Map(BASES.map((b) => [b.code, b]));
const TCS = X.D2X_TREASURE_CLASSES;
const skills = Object.values(X.D2X_SKILLS);
const SKILL_BY = new Map(rows(skillsJ).filter((s) => s.skill).flatMap((s) => [[s['*Id'], s], [s.skill.toLowerCase(), s]]));
const skillOf = (p) => SKILL_BY.get(typeof p === 'number' || /^\d+$/.test(p) ? +p : String(p).toLowerCase());
const has = (arr, k, key) => arr.some((x) => x[k] === key);

// ───────────────────────── counts ─────────────────────────
section('Counts after the scope filters');
const count = (label, n) => console.log(`  ${label.padEnd(24)} ${n}`);
const fromOf = (k) => skills.filter((s) => s.from.includes(k)).length;
count('weapons / armor / misc', `${W.length} / ${A.length} / ${M.length} (${BASES.length} bases)`);
count('item types', Object.keys(X.D2X_ITEM_TYPES).length);
count('prefixes / suffixes', `${X.D2X_PREFIXES.length} / ${X.D2X_SUFFIXES.length}, automagic ${X.D2X_AUTOMAGIC.length}`);
count('rare name words', `${X.D2X_RARE_PREFIXES.length} + ${X.D2X_RARE_SUFFIXES.length}`);
count('superior mods', X.D2X_QUALITY.length);
count('uniques', X.D2X_UNIQUES.length);
count('sets / set items', `${X.D2X_SETS.length} / ${X.D2X_SET_ITEMS.length}`);
count('runewords', X.D2X_RUNEWORDS.length);
count('runes / gems', `${X.D2X_RUNES.length} / ${X.D2X_GEMS.length}`);
count('classes', Object.keys(X.D2X_CLASSES).join(' '));
count('Act 1 areas', X.D2X_AREAS.length);
count('monsters', `${Object.keys(X.D2X_MONSTERS).length} (${Object.values(X.D2X_MONSTERS).filter((m) => m.name).length} named)`);
count('superuniques', X.D2X_SUPERUNIQUES.length);
count('treasure classes', `${Object.keys(TCS).length} (${Object.values(TCS).filter((t) => t.auto).length} automatic)`);
count('skills', `${skills.length}: class ${fromOf('class')}, monster ${fromOf('monster')}, umod ${fromOf('umod')}, hireling ${fromOf('hireling')}, summon ${fromOf('summon')}, missile ${fromOf('missile')}`);
count('named-only skills', Object.keys(X.D2X_SKILL_REFS).length);
count('missiles / states', `${Object.keys(X.D2X_MISSILES).length} / ${Object.keys(X.D2X_STATES).length}`);
count('hirelings / names', `${X.D2X_HIRELINGS.length} / ${Object.keys(X.D2X_HIRELING_NAMES).length}`);
count('gamble bases', X.D2X_GAMBLE.length);

section('Files');
// (types.ts is written by hand)
check('every generated src/data/d2x file starts with the generated-file header', files.filter((f) => f !== 'types.ts' && !fs.readFileSync(path.join(D2X, f), 'utf8').startsWith(HEAD)));

// ───────────────────────── scope ─────────────────────────
section('Scope: before the Warlock expansion, nothing still ladder-only');
/** every property list in the data, with where it is */
const allProps = [
  ...[...X.D2X_PREFIXES, ...X.D2X_SUFFIXES, ...X.D2X_AUTOMAGIC].map((a) => [`affix ${a.id}`, a.props]),
  ...X.D2X_QUALITY.map((q) => [`superior ${q.id}`, q.props]),
  ...X.D2X_UNIQUES.map((u) => [`unique ${u.key}`, u.props]),
  ...X.D2X_SET_ITEMS.map((s) => [`set item ${s.key}`, [...s.props, ...(s.bonus ?? []).flat()]]),
  ...X.D2X_SETS.map((s) => [`set ${s.id}`, [...s.partial.flatMap((p) => p.props), ...s.full]]),
  ...X.D2X_RUNEWORDS.map((r) => [`runeword ${r.id}`, r.props]),
  ...[...X.D2X_RUNES, ...X.D2X_GEMS].map((g) => [`socketable ${g.id}`, [...g.weapon, ...g.armor, ...g.shield]]),
  ...Object.values(X.D2X_MONSTERS).filter((m) => m.props).map((m) => [`monster ${m.id}`, m.props.flat()]),
];
check('no Warlock class', Object.keys(X.D2X_CLASSES).filter((c) => c === WARLOCK));
check('no Warlock item type', Object.keys(X.D2X_ITEM_TYPES).filter((t) => WARLOCK_TYPES.has(t)));
check('no base of a Warlock item type', BASES.filter((b) => WARLOCK_TYPES.has(b.type) || WARLOCK_TYPES.has(b.type2)).map((b) => b.code));
const kindOf = (b) => (W.includes(b) ? 'weapons' : A.includes(b) ? 'armor' : 'misc');
check('no base the expansion added (all are in 2.7)', BASES.filter((b) => !rows(R27[kindOf(b)]).some((r) => r.code === b.code)).map((b) => b.code));
check(
  'no affix for the Warlock',
  [...X.D2X_PREFIXES, ...X.D2X_SUFFIXES, ...X.D2X_AUTOMAGIC].filter((a) => a.cls === WARLOCK || a.reqCls === WARLOCK || a.itypes.some((t) => WARLOCK_TYPES.has(t))).map((a) => a.id),
);
check('no Warlock set or set item', [...X.D2X_SETS.filter((s) => WARLOCK_SETS.has(s.id)).map((s) => s.id), ...X.D2X_SET_ITEMS.filter((s) => WARLOCK_SETS.has(s.set)).map((s) => s.key)]);
check('no Warlock skill', [...skills, ...Object.values(X.D2X_SKILL_REFS)].filter((s) => s.cls === WARLOCK).map((s) => s.en ?? s.id));
check('no skill the expansion added (all are in 2.7)', [...Object.keys(X.D2X_SKILLS), ...Object.keys(X.D2X_SKILL_REFS)].filter((n) => !rows(R27.skills).some((s) => s.skill === n)));
// what only the Warlock gets anything from: his class skills (code war), his tabs, his skills, a random class past the seven
check(
  'no property for the Warlock',
  allProps.flatMap(([w, ps]) =>
    ps
      .filter((p) => p.c === WARLOCK || (p.c === 'skilltab' && isWarlockTab(p.p)) || (SKILL_PROPS.has(p.c) && skillOf(p.p)?.charclass === WARLOCK) || (p.c === 'randclassskill' && p.max > 6))
      .map((p) => `${w} ${p.c} ${p.p ?? ''}`),
  ),
);
// rows the expansion added have no string in the D2CE tables, which are pinned before it
const noString = (key) => S.zh[key] === undefined;
check('every unique, set item, set and runeword has a D2CE string (none came with the Warlock)', [
  ...X.D2X_UNIQUES.filter((u) => noString(u.key)).map((u) => u.key),
  ...X.D2X_SET_ITEMS.filter((s) => noString(s.key)).map((s) => s.key),
  ...X.D2X_SETS.filter((s) => noString(s.id)).map((s) => s.id),
  ...X.D2X_RUNEWORDS.filter((r) => noString(r.id)).map((r) => r.id),
]);
const season = latestSeason(uniqueJ, setItemsJ, runesJ);
const season27 = latestSeason(R27.uniqueitems, R27.setitems, R27.runes);
// uniques by *ID: index repeats (Azurewrath's unused first row, the eight Rainbow Facets)
const U33 = by(uniqueJ, '*ID');
const SI33 = by(setItemsJ, 'index');
const RW33 = by(runesJ, 'Name');
const [U27, SI27, RW27] = [by(R27.uniqueitems, '*ID'), by(R27.setitems, 'index'), by(R27.runes, 'Name')];
// left out only when ladder-only both now and in 2.7, before the Warlock expansion (a row 2.7 lacks: now)
const stillLadder = (pinned, old) => ladderOnly(pinned, season) && (!old || ladderOnly(old, season27));
check(`nothing ladder-only both in the pinned tables (latest season ${season}) and in 2.7 (latest season ${season27})`, [
  ...X.D2X_UNIQUES.filter((u) => stillLadder(U33.get(u.id), U27.get(u.id))).map((u) => u.key),
  ...X.D2X_SET_ITEMS.filter((s) => stillLadder(SI33.get(s.key), SI27.get(s.key))).map((s) => s.key),
  ...X.D2X_RUNEWORDS.filter((r) => stillLadder(RW33.get(r.id), RW27.get(r.id))).map((r) => r.id),
]);
// Season 15 made nine old uniques and Angelic Raiment ladder-only (lastLadderSeason 15 and 16 in the
// pinned tables) and changed some: The Battlebranch's item level went from 34 to 30, the full set
// got +1 to all skills. 2.7 has them as ordinary items, and they are in as 2.7 has them.
{
  const s15 = ['Gravenspine', 'The Battlebranch', 'Bane Ash', 'Pluckeye', 'Piercerib', 'Blinkbats Form', 'The Ward', 'Manald Heal', 'Bloodletter'];
  const angelic = ['Angelic Sickle', 'Angelic Mantle', 'Angelic Halo', 'Angelic Wings'];
  const raiment = X.D2X_SETS.find((s) => s.id === 'Angelical Raiment');
  const bad = [
    ...s15.filter((k) => !has(X.D2X_UNIQUES, 'key', k)),
    ...angelic.filter((k) => !has(X.D2X_SET_ITEMS, 'key', k)),
    ...(raiment ? [] : ['set Angelical Raiment']),
    ...(X.D2X_UNIQUES.find((u) => u.key === 'The Battlebranch')?.lvl === 34 ? [] : ['The Battlebranch: not item level 34']),
    ...(raiment?.full.some((p) => p.c === 'allskills') ? ['Angelical Raiment: the full set has +1 to all skills'] : []),
  ];
  check("season 15's ladder-only uniques and Angelic Raiment are in, as 2.7 has them (The Battlebranch item level 34, no +1 to all skills for the full set)", bad);
}
check('the 2.6 runewords, ladder-only until season 14, are in', ['Bulwark', 'Cure', 'Ground', 'Hearth', 'Temper', 'Mosaic', 'Metamorphosis'].filter((en) => !has(X.D2X_RUNEWORDS, 'en', en)));
check(
  'every treasure class entry is a class in the data or an imported base, none out of scope',
  Object.entries(TCS).flatMap(([n, t]) => t.items.filter((e) => (e.tc ? !TCS[e.tc] || OUT_OF_SCOPE_TC.test(e.tc) : !BASE.has(e.item))).map((e) => `${n}: ${e.tc ?? e.item}`)),
);
check('every base and set piece the uniques, sets and gambling name is in the data', [
  ...X.D2X_UNIQUES.filter((u) => !BASE.has(u.code)).map((u) => `unique ${u.key} ${u.code}`),
  ...X.D2X_SET_ITEMS.filter((s) => !BASE.has(s.code)).map((s) => `set item ${s.key} ${s.code}`),
  ...X.D2X_SETS.flatMap((s) => s.pieces.filter((p) => !has(X.D2X_SET_ITEMS, 'key', p)).map((p) => `set ${s.id} ${p}`)),
  ...X.D2X_GAMBLE.filter((c) => !BASE.has(c)),
]);

// ───────────────────────── 2.7 ─────────────────────────
// The pinned tables are 3.x and carry what the Warlock expansion changed in rows that were there
// before it. Every value the game reads must be 2.7's: the expected values are worked out here from
// the 2.7 rows, as src/data/d2x/types.ts documents the generated fields.
section('Every row as D2R 2.7 has it');
const SKILL27 = new Map(rows(R27.skills).filter((s) => s.skill).flatMap((s) => [[s['*Id'], s], [s.skill.toLowerCase(), s]]));
/** a row's properties as D2Prop: codes lower-cased, commented-out (*) codes skipped, skill parameters by name */
function props27(r, n, code, par, min, max, chance) {
  const out = [];
  for (let i = 1; i <= n; i++) {
    const c = r[code(i)];
    if (c === undefined || c === '' || String(c).startsWith('*')) continue;
    const o = { c: String(c).trim().toLowerCase() };
    const p = r[par(i)];
    if (p !== undefined && p !== null && p !== '') {
      o.p = SKILL_PROPS.has(o.c) ? (SKILL27.get(typeof p === 'number' || /^\d+$/.test(p) ? +p : String(p).toLowerCase())?.skill ?? String(p)) : p;
    }
    o.min = r[min(i)] ?? 0;
    o.max = r[max(i)] ?? o.min;
    if (chance && r[chance(i)]) o.chance = r[chance(i)];
    out.push(o);
  }
  return out;
}
const NPCS = ['Charsi', 'Gheed', 'Akara', 'Fara', 'Lysander', 'Drognan', 'Hratli', 'Alkor', 'Ormus', 'Elzix', 'Asheara', 'Cain', 'Halbu', 'Jamella', 'Larzuk', 'Malah', 'Anya'];
const SHOP = [['min', 'Min'], ['max', 'Max'], ['magicMin', 'MagicMin'], ['magicMax', 'MagicMax'], ['magicLvl', 'MagicLvl']];
/** who stocks a base: an NPC with any count does, with all its columns */
function shop27(r) {
  const o = {};
  for (const n of NPCS) {
    if (!SHOP.some(([k, c]) => k !== 'magicLvl' && r[n + c] > 0)) continue;
    o[n.toLowerCase()] = Object.fromEntries(SHOP.filter(([, c]) => r[n + c] !== undefined).map(([k, c]) => [k, r[n + c]]));
  }
  return Object.keys(o).length ? o : undefined;
}
{
  const bad = [];
  const chargeCost = new Map(rows(R27.books).filter((b) => b.BookSpellCode).map((b) => [b.BookSpellCode, b.CostPerCharge]));
  for (const [kind, list] of [['weapons', W], ['armor', A], ['misc', M]]) {
    const old = by(R27[kind], 'code');
    for (const b of list) {
      const r = old.get(b.code);
      if (!r) continue;
      const f = (field, want) => mismatch(bad, `${kind} ${b.code}`, field, want, b[field]);
      f('type', r.type);
      f('w', r.invwidth);
      f('h', r.invheight);
      f('qlvl', r.level ?? 0);
      f('reqLvl', r.levelreq ?? 0);
      f('reqStr', opt(r.reqstr));
      f('reqDex', opt(r.reqdex));
      f('rarity', r.rarity ?? 0);
      f('spawnable', !!r.spawnable);
      f('cost', r.cost ?? 0);
      f('dur', opt(r.durability));
      f('sockets', opt(r.gemsockets));
      f('shop', shop27(r));
      f('perm', r.PermStoreItem ? true : undefined);
      f('shopMagic', r.bitfield1 & 1 ? true : undefined);
      f('chargeCost', chargeCost.get(b.code));
      if (kind === 'weapons') {
        f('dmg1', r.maxdam ? [r.mindam ?? 0, r.maxdam] : undefined);
        f('dmg2', r['2handed'] ? [r['2handmindam'] ?? 0, r['2handmaxdam'] ?? 0] : undefined);
        f('throwDmg', r.maxmisdam ? [r.minmisdam ?? 0, r.maxmisdam] : undefined);
        f('wsm', r.speed ?? 0);
      }
      if (kind === 'armor') {
        f('ac', [r.minac ?? 0, r.maxac ?? 0]);
        f('block', opt(r.block));
        f('speed', opt(r.speed));
      }
    }
  }
  check('bases: type, size, requirements, damage, defense, sockets, durability, rarity, cost, shops, tomes\' cost per scroll', bad);
}
{
  const bad = [];
  const old = by(R27.uniqueitems, '*ID');
  for (const u of X.D2X_UNIQUES) {
    const r = old.get(u.id);
    if (!r) continue;
    if (r.index !== u.key) bad.push(`unique ${u.id}: 2.7 row is ${r.index}, not ${u.key}`);
    const f = (field, want) => mismatch(bad, `unique ${u.key}`, field, want, u[field]);
    f('code', r.code);
    f('lvl', r.lvl ?? 0);
    f('reqLvl', r['lvl req'] ?? 0);
    f('rarity', r.rarity ?? 0);
    // 2.7 calls the drop flag "enabled", the 3.x tables "spawnable"
    f('spawnable', !!r.enabled);
    f('props', props27(r, 12, (i) => `prop${i}`, (i) => `par${i}`, (i) => `min${i}`, (i) => `max${i}`));
  }
  const oldPiece = by(R27.setitems, 'index');
  for (const s of X.D2X_SET_ITEMS) {
    const r = oldPiece.get(s.key);
    if (!r) continue;
    const f = (field, want) => mismatch(bad, `set item ${s.key}`, field, want, s[field]);
    f('set', r.set);
    f('code', r.item);
    f('lvl', r.lvl ?? 0);
    f('reqLvl', r['lvl req'] ?? 0);
    f('addFunc', r['add func'] ?? 0);
    f('props', props27(r, 9, (i) => `prop${i}`, (i) => `par${i}`, (i) => `min${i}`, (i) => `max${i}`));
    const one = (c) => props27(r, 1, () => `aprop${c}`, () => `apar${c}`, () => `amin${c}`, () => `amax${c}`);
    const bonus = [1, 2, 3, 4, 5].map((n) => [...one(`${n}a`), ...one(`${n}b`)]);
    while (bonus.length && !bonus[bonus.length - 1].length) bonus.pop();
    f('bonus', bonus.length ? bonus : undefined);
  }
  const oldSet = by(R27.sets, 'index');
  for (const s of X.D2X_SETS) {
    const r = oldSet.get(s.id);
    if (!r) continue;
    const one = (c) => props27(r, 1, () => `PCode${c}`, () => `PParam${c}`, () => `PMin${c}`, () => `PMax${c}`);
    const partial = [2, 3, 4, 5].map((n) => ({ n, props: [...one(`${n}a`), ...one(`${n}b`)] })).filter((p) => p.props.length);
    mismatch(bad, `set ${s.id}`, 'partial', partial, s.partial);
    mismatch(bad, `set ${s.id}`, 'full', props27(r, 8, (i) => `FCode${i}`, (i) => `FParam${i}`, (i) => `FMin${i}`, (i) => `FMax${i}`), s.full);
  }
  const oldRw = by(R27.runes, 'Name');
  for (const w of X.D2X_RUNEWORDS) {
    const r = oldRw.get(w.id);
    if (!r) continue;
    mismatch(bad, `runeword ${w.id}`, 'runes', numbered(r, 6, (i) => `Rune${i}`).map((x) => +x.slice(1)), w.runes);
    mismatch(bad, `runeword ${w.id}`, 'itypes', itypes(r, 6), w.itypes);
    mismatch(bad, `runeword ${w.id}`, 'props', props27(r, 7, (i) => `T1Code${i}`, (i) => `T1Param${i}`, (i) => `T1Min${i}`, (i) => `T1Max${i}`), w.props);
  }
  // affixes are by row: the same row of 2.7 must be the same affix
  for (const [t, list] of [['magicprefix', X.D2X_PREFIXES], ['magicsuffix', X.D2X_SUFFIXES], ['automagic', X.D2X_AUTOMAGIC]]) {
    for (const a of list) {
      const r = R27[t][a.id];
      const where = `${t} ${a.id}`;
      if (!r || S.en[r.Name] !== a.en) {
        bad.push(`${where}: 2.7 row ${a.id} is ${r?.Name}, not ${a.en}`);
        continue;
      }
      const f = (field, want) => mismatch(bad, where, field, want, a[field]);
      f('level', r.level ?? 0);
      f('maxLevel', opt(r.maxlevel));
      f('reqLvl', r.levelreq ?? 0);
      f('group', r.group ?? 0);
      f('freq', r.frequency ?? 0);
      f('spawnable', !!r.spawnable);
      f('itypes', itypes(r, 7));
      f('props', props27(r, 3, (i) => `mod${i}code`, (i) => `mod${i}param`, (i) => `mod${i}min`, (i) => `mod${i}max`));
    }
  }
  const gems = by(R27.gems, 'code');
  for (const g of [...X.D2X_RUNES, ...X.D2X_GEMS]) {
    const r = gems.get(g.id);
    const mods = (k) => props27(r, 3, (i) => `${k}Mod${i}Code`, (i) => `${k}Mod${i}Param`, (i) => `${k}Mod${i}Min`, (i) => `${k}Mod${i}Max`);
    mismatch(bad, `socketable ${g.id}`, 'mods', [mods('weapon'), mods('helm'), mods('shield')], [g.weapon, g.armor, g.shield]);
  }
  check('uniques, set items, sets, runewords, affixes, runes and gems: levels, rarity, properties', bad);
}
{
  const bad = [];
  const old = by(R27.monstats, 'Id');
  const DIFF = ['', '(N)', '(H)'];
  const col = (b, d) => (d === 0 ? b : `${b === 'minHP' ? 'MinHP' : b === 'maxHP' ? 'MaxHP' : b}${DIFF[d]}`);
  for (const m of Object.values(X.D2X_MONSTERS)) {
    const r = old.get(m.id);
    if (!r) {
      bad.push(`monster ${m.id}: not in 2.7`);
      continue;
    }
    mismatch(bad, `monster ${m.id}`, 'area', opt(r.areaId), m.area);
    mismatch(bad, `monster ${m.id}`, 'ai', r.AI, m.ai);
    m.diff.forEach((x, d) => {
      const v = (b) => r[col(b, d)] ?? 0;
      const where = `monster ${m.id} ${['normal', 'nightmare', 'hell'][d]}`;
      mismatch(bad, where, 'level', v('Level'), x.level);
      mismatch(bad, where, 'hp', [v('minHP'), v('maxHP')], x.hp);
      mismatch(bad, where, 'ac', v('AC'), x.ac);
      mismatch(bad, where, 'xp', v('Exp'), x.xp);
      mismatch(bad, where, 'a1', v('A1MaxD') || v('A1TH') ? [v('A1MinD'), v('A1MaxD'), v('A1TH')] : undefined, x.a1);
      mismatch(bad, where, 'res', ['ResDm', 'ResMa', 'ResFi', 'ResLi', 'ResCo', 'ResPo'].map(v), x.res);
      const tc = {};
      for (const [k, c] of [['regular', 'TreasureClass'], ['champ', 'TreasureClassChamp'], ['unique', 'TreasureClassUnique'], ['quest', 'TreasureClassQuest']]) if (v(c)) tc[k] = v(c);
      mismatch(bad, where, 'tc', tc, x.tc);
    });
    if (r.MonProp) {
      const p = rows(R27.monprop).find((x) => x.Id === r.MonProp);
      const want = ['', ' (N)', ' (H)'].map((s) => props27(p, 6, (i) => `prop${i}${s}`, (i) => `par${i}${s}`, (i) => `min${i}${s}`, (i) => `max${i}${s}`, (i) => `chance${i}${s}`));
      mismatch(bad, `monster ${m.id}`, 'props', want.some((x) => x.length) ? want : undefined, m.props);
    }
  }
  const lv = by(R27.levels, 'Id');
  for (const a of X.D2X_AREAS) {
    const r = lv.get(a.id);
    const f = (field, want) => mismatch(bad, `area ${a.id}`, field, want, a[field]);
    f('lvl', DIFF.map((s) => r[`MonLvlEx${s}`] ?? 0));
    f('den', DIFF.map((s) => r[`MonDen${s}`] ?? 0));
    f('packs', DIFF.map((s) => [r[`MonUMin${s}`] ?? 0, r[`MonUMax${s}`] ?? 0]));
    f('numMon', r.NumMon ?? 0);
    for (const p of ['mon', 'nmon', 'umon']) f(p, numbered(r, 25, (i) => `${p}${i}`).filter((id) => X.D2X_MONSTERS[id]));
  }
  const su = by(R27.superuniques, 'Superunique');
  for (const s of X.D2X_SUPERUNIQUES) {
    const r = su.get(s.key);
    mismatch(bad, `superunique ${s.key}`, 'tc', [r.TC, r['TC(N)'], r['TC(H)']], s.tc);
    mismatch(bad, `superunique ${s.key}`, 'mods', [r.Mod1, r.Mod2, r.Mod3].filter(Boolean), s.mods);
    mismatch(bad, `superunique ${s.key}`, 'mon', r.Class, s.mon);
  }
  const ml = rows(R27.monlvl).sort((a, b) => a.Level - b.Level);
  X.D2X_MONLVL.forEach((x, i) => {
    const t = (c) => DIFF.map((s) => ml[i][`L-${c}${s}`]);
    mismatch(bad, `monlvl ${i}`, 'row', { ac: t('AC'), th: t('TH'), hp: t('HP'), dm: t('DM'), xp: t('XP') }, x);
  });
  check('monsters, monster properties, areas, superuniques, monster levels', bad);
}
{
  const bad = [];
  const order = rows(R27.playerclass).sort((a, b) => a.lineNumber - b.lineNumber);
  for (const [code, c] of Object.entries(X.D2X_CLASSES)) {
    const r = rows(R27.charstats).find((x) => x.class === c.en);
    // growth is kept in quarter points
    const q = (k) => r[k] / 4;
    const want = {
      id: order.findIndex((p) => p.Code === code), str: r.str, dex: r.dex, vit: r.vit, ene: r.int, stamina: r.stamina, hpadd: r.hpadd,
      lifePerLvl: q('LifePerLevel'), manaPerLvl: q('ManaPerLevel'), staminaPerLvl: q('StaminaPerLevel'), lifePerVit: q('LifePerVitality'),
      staminaPerVit: q('StaminaPerVitality'), manaPerEne: q('ManaPerMagic'), toHitFactor: r.ToHitFactor, blockFactor: r.BlockFactor,
      hpPotion: r.HealthPotionPercent, mpPotion: r.ManaPotionPercent,
    };
    for (const [k, v] of Object.entries(want)) mismatch(bad, `class ${code}`, k, v, c[k]);
  }
  const DL = {
    resistPenalty: 'ResistPenalty', deathXpLoss: 'DeathExpPenalty', monsterSkillBonus: 'MonsterSkillBonus', lifeStealDivisor: 'LifeStealDivisor',
    manaStealDivisor: 'ManaStealDivisor', staticFieldMin: 'StaticFieldMin', mercVsBoss: 'MercenaryDamagePercentVSBoss', gambleUnique: 'GambleUnique',
    gambleUber: 'GambleUber', gambleUltra: 'GambleUltra',
  };
  const diffs = rows(R27.difficultylevels).sort((a, b) => a.lineNumber - b.lineNumber);
  X.D2X_DIFFICULTIES.forEach((d, i) => {
    for (const [k, c] of Object.entries(DL)) mismatch(bad, `difficulty ${d.id}`, k, diffs[i][c], d[k]);
  });
  const ratios = rows(R27.itemratio).filter((r) => r.Version === 1);
  for (const x of X.D2X_ITEM_RATIO) {
    const r = ratios.find((y) => !!y.Uber === x.uber && !!y['Class Specific'] === x.cls);
    for (const q of ['Unique', 'Set', 'Rare', 'Magic']) mismatch(bad, `itemratio uber ${x.uber} class ${x.cls}`, q, { ratio: r[q], div: r[`${q}Divisor`], min: r[`${q}Min`] }, x[q.toLowerCase()]);
  }
  for (const h of X.D2X_HIRELINGS) {
    const old = rows(R27.hireling).filter((r) => r.Version === 100 && r.Id === h.id).sort((a, b) => a.Level - b.Level);
    mismatch(bad, `hireling ${h.id}`, 'bands', old.map((r) => r.Level), h.bands.map((b) => b.level));
    h.bands.forEach((b, i) => {
      const r = old[i];
      if (!r) return;
      const where = `hireling ${h.id} level ${b.level}`;
      for (const [k, c] of [['hp', 'HP'], ['hpPerLvl', 'HP/Lvl'], ['def', 'Defense'], ['ar', 'AR'], ['gold', 'Gold']]) mismatch(bad, where, k, r[c], b[k]);
      mismatch(bad, where, 'dmg', [r['Dmg-Min'], r['Dmg-Max']], b.dmg);
      mismatch(bad, where, 'skills', numbered(r, 6, (n) => `Skill${n}`), b.skills.map((s) => s.skill));
    });
  }
  for (const [npc, p] of Object.entries(X.D2X_NPC_PRICES)) {
    const r = rows(R27.npc).find((x) => x.npc === npc);
    mismatch(bad, `npc ${npc}`, 'prices', [r['sell mult'], r['buy mult'], r['rep mult']].map((v) => v / 1024), [p.heroBuys, p.heroSells, p.repair]);
  }
  mismatch(bad, 'gamble', 'bases', rows(R27.gamble).map((r) => r.code).filter((c) => BASE.has(c)), X.D2X_GAMBLE);
  check('classes, difficulties, item ratios, hirelings, NPC prices, gambling', bad);
}

// ───────────────────────── names ─────────────────────────
section('Names');
{
  // a row in scope is in the data, or in the report (unnamed, or left out by a scope rule)
  const listed = (key) => report.includes(`\`${key}\``);
  const keys = (arr, k) => new Set(arr.map((x) => x[k]));
  const [uk, sk, ss, rk] = [keys(X.D2X_UNIQUES, 'key'), keys(X.D2X_SET_ITEMS, 'key'), keys(X.D2X_SETS, 'id'), keys(X.D2X_RUNEWORDS, 'id')];
  const out = [
    ...rows(uniqueJ).filter((r) => r.code && !uk.has(r.index) && !listed(r.index)).map((r) => `unique ${r.index}`),
    ...rows(setItemsJ).filter((r) => !sk.has(r.index) && !listed(r.index)).map((r) => `set item ${r.index}`),
    ...rows(setsJ).filter((r) => !ss.has(r.index) && !listed(r.index)).map((r) => `set ${r.index}`),
    ...rows(runesJ).filter((r) => r.complete && !rk.has(r.Name) && !listed(r.Name)).map((r) => `runeword ${r.Name}`),
  ];
  check('every unique, set item, set and runeword is in the data or listed in tools/d2-names/report.md', out);
  check('every one in the data has a name', [...X.D2X_UNIQUES, ...X.D2X_SET_ITEMS, ...X.D2X_SETS, ...X.D2X_RUNEWORDS].filter((x) => !x.name).map((x) => x.key ?? x.id));
}
{
  // every name in the data, wherever it is
  const named = [];
  const walk = (v, where) => {
    if (Array.isArray(v)) v.forEach((x, i) => walk(x, `${where}[${i}]`));
    else if (v && typeof v === 'object') for (const [k, x] of Object.entries(v)) k === 'name' && typeof x === 'string' ? named.push([where, x]) : walk(x, `${where}.${k}`);
  };
  for (const [k, v] of Object.entries(X)) walk(v, k);
  for (const h of X.D2X_HIRELINGS) if (h.type) named.push([`D2X_HIRELINGS ${h.id} type`, h.type]);
  // the official strings of what we rename: uniques, sets, runewords, affixes, rare words, monsters, areas, NPCs, hirelings
  const world = await strings('monsters', 'levels', 'npcs', 'mercenaries');
  const proper = new Set();
  const add = (zh) => zh && proper.add(zh.trim());
  for (const r of [...rows(uniqueJ), ...rows(setItemsJ), ...rows(setsJ)]) add(S.zh[r.index]);
  for (const r of rows(runesJ)) add(S.zh[r.Name]);
  for (const t of ['magicprefix', 'magicsuffix', 'automagic']) for (const r of rows(R27[t])) add(S.zh[r.Name]);
  for (const t of ['rareprefix', 'raresuffix']) for (const r of rows(await load(DATA, t))) add(S.zh[r.name]);
  for (const v of Object.values(world.zh)) add(v);
  // generic words keep their official names by design: base items and skills (but those bases.json
  // and skills.json rename), gems, low quality, skill trees
  const ours = (f) => JSON.parse(fs.readFileSync(path.join(ROOT, `tools/d2-names/${f}.json`), 'utf8'));
  const renamedBases = ours('bases');
  const renamedSkills = ours('skills');
  const generic = new Set([
    ...BASES.filter((b) => !renamedBases[b.code]).map((b) => b.name),
    ...X.D2X_GEMS.map((g) => g.name),
    ...X.D2X_LOW_QUALITY.map((q) => q.name),
    ...Object.values(X.D2X_CLASSES).flatMap((c) => c.tabs.map((t) => t.name)),
    ...Object.entries({ ...X.D2X_SKILLS, ...X.D2X_SKILL_REFS }).filter(([n]) => !renamedSkills[n]).map(([, s]) => s.name),
  ]);
  check(`no name of ours (${named.length}) is an official proper-noun string`, named.filter(([, n]) => proper.has(n.trim()) && !generic.has(n)).map(([w, n]) => `${w} ${n}`));
  // nor its own row's official with only 的 or 之, a middle dot or a space changed (风的力 for 风之力:
  // tools/d2-names/style.md, hard rule 1), the official as the names files keep it (D2CE's zhCN)
  const zhKey = (s) => s.trim().replace(/[的之·・\s]/g, '');
  const sameZh = [];
  for (const f of fs.readdirSync(path.join(ROOT, 'tools/d2-names')).filter((f) => f.endsWith('.json') && !f.startsWith('glossary'))) {
    for (const [k, v] of Object.entries(ours(f.replace(/\.json$/, '')))) if (v?.name && v.official && zhKey(v.name) && zhKey(v.name) === zhKey(v.official)) sameZh.push(`${f} ${k} ${v.name} = ${v.official}`);
  }
  check("no name of ours is its row's official Chinese with only 的, 之, · or spaces changed", sameZh);
  const terms = JSON.parse(fs.readFileSync(path.join(ROOT, 'tools/d2-names/glossary.json'), 'utf8')).map((g) => g.official).filter((o) => o && o.length >= 2);
  const leaks = [];
  for (const f of files) {
    const text = fs.readFileSync(path.join(D2X, f), 'utf8');
    for (const t of terms) if (text.includes(t)) leaks.push(`${f}: ${t}`);
  }
  check('no official transliteration the glossary replaces, anywhere in src/data/d2x', leaks);
  check(
    'runes are "N 号符文", 1–33, the glyph the number',
    [...X.D2X_RUNES.filter((r, i) => !(r.num === i + 1 && r.name === `${i + 1} 号符文` && r.glyph === String(i + 1))).map((r) => `${r.id} ${r.name} ${r.glyph}`), ...(X.D2X_RUNES.length === 33 ? [] : [`${X.D2X_RUNES.length} runes`])],
  );
  const official = new Set(Object.values(S.zh).map((z) => z?.trim()));
  check('gems and generic bases keep the official name', [
    ...X.D2X_GEMS.filter((g) => g.name !== S.zh[g.id]).map((g) => `${g.id} ${g.name}`),
    ...BASES.filter((b) => !renamedBases[b.code] && b.type !== 'rune' && !official.has(b.name.trim())).map((b) => `${b.code} ${b.name}`),
  ]);
}

// ───────────────────────── English names ─────────────────────────
section('English names');
{
  // case, "the", apostrophes, spaces and hyphens aside, as tools/d2-names/style-en.md compares
  const norm = (s) => s.toLowerCase().replace(/\bthe\b/g, '').replace(/['’\s-]/g, '');
  // ...and "of", "a", "an", a possessive 's and the order of the words too: what a name reads as
  // against its row's own English (style-en.md, hard rule 1: "Wind Force" and "Force of the Wind" are
  // Windforce's words, "Oak Heart" Heart of the Oak's)
  const readsAs = (s) => {
    const w = s.toLowerCase().replace(/['’]s\b/g, '').replace(/['’]/g, '').split(/[\s-]+/).filter((x) => x && !['of', 'the', 'a', 'an'].includes(x));
    return [w.join(''), [...w].sort().join(' ')];
  };
  const sameWords = (a, b) => {
    const [x, y] = [readsAs(a), readsAs(b)];
    return !!x[0] && (x[0] === y[0] || x[1] === y[1]);
  };
  const ours = (f) => JSON.parse(fs.readFileSync(path.join(ROOT, `tools/d2-names/${f}.json`), 'utf8'));
  const renamedBases = ours('bases');
  const renamedSkills = ours('skills');
  const merc = await strings('mercenaries');
  // every row whose name is ours, with D2's English: { where, group, files, zh, nameEn, en }; `files`
  // are the names files the importer takes the row's names from, in its order
  const of = (where, group, files, arr, key) => arr.map((x) => ({ where: `${where} ${key(x)}`, group, files, zh: x.name, nameEn: x.nameEn, en: x.en }));
  // a skill named by a runeword's string takes our runeword names (Delirium's change)
  const runewordOf = new Map(X.D2X_RUNEWORDS.map((r) => [r.name, r]));
  const allSkills = Object.entries({ ...X.D2X_SKILLS, ...X.D2X_SKILL_REFS });
  const hire27 = new Map(rows(R27.hireling).filter((h) => h.Version === 100).map((h) => [h.Id, h]));
  const renamed = [
    ...of('unique', 'items', ['uniques'], X.D2X_UNIQUES, (u) => u.key),
    ...of('set item', 'items', ['sets'], X.D2X_SET_ITEMS, (s) => s.key),
    ...of('set', 'items', ['sets'], X.D2X_SETS, (s) => s.id),
    ...of('runeword', 'items', ['runewords'], X.D2X_RUNEWORDS, (r) => r.id),
    ...of('rune', 'runes', [], X.D2X_RUNES, (r) => r.id),
    ...of('prefix', 'prefixes', ['prefixes'], X.D2X_PREFIXES, (a) => a.id),
    ...of('suffix', 'suffixes', ['suffixes'], X.D2X_SUFFIXES, (a) => a.id),
    ...of('automagic', 'automagic', ['prefixes', 'suffixes'], X.D2X_AUTOMAGIC, (a) => a.id),
    ...of('rare prefix', 'rare prefixes', ['rare-prefixes'], X.D2X_RARE_PREFIXES, (w) => w.id),
    ...of('rare suffix', 'rare suffixes', ['rare-suffixes'], X.D2X_RARE_SUFFIXES, (w) => w.id),
    ...of('base', 'bases', ['bases'], BASES.filter((b) => renamedBases[b.code] && !renamedBases[b.code].generic), (b) => b.code),
    ...of('monster', 'monsters', ['monsters', 'npcs'], Object.values(X.D2X_MONSTERS).filter((m) => m.name), (m) => m.id),
    ...of('superunique', 'superuniques', ['monsters'], X.D2X_SUPERUNIQUES, (s) => s.key),
    ...of('area', 'areas', ['areas'], X.D2X_AREAS, (a) => a.id),
    ...['prefix', 'suffix', 'title'].flatMap((k) => of(`unique monster ${k}`, `unique monster ${k}${k === 'title' ? 's' : 'es'}`, [`monster-${k}${k === 'title' ? 's' : 'es'}`], X.D2X_UNIQUE_NAMES[k], (w) => w.key)),
    ...Object.entries(X.D2X_HIRELING_NAMES).map(([k, v]) => ({ where: `hireling name ${k}`, group: 'hireling names', files: ['mercenaries'], zh: v.name, nameEn: v.nameEn, en: merc.en[k] })),
    ...X.D2X_HIRELINGS.filter((h) => h.type).map((h) => ({ where: `hireling ${h.id} type`, group: 'hireling types', files: ['mercenaries'], zh: h.type, nameEn: h.typeEn, en: hire27.get(h.id)?.Hireling })),
    // skills.json's, and a skill whose name is a runeword's
    ...allSkills.filter(([n, s]) => s.name && (renamedSkills[n] || runewordOf.has(s.name))).map(([n, s]) => ({ where: `skill ${n}`, group: 'skills', files: ['skills', 'runewords'], zh: s.name, nameEn: s.nameEn, en: s.en })),
  ];
  const named = renamed.filter((r) => r.nameEn);
  check(`every renamed row (${renamed.length}) has an English name of ours, nameEn`, renamed.filter((r) => !r.nameEn).map((r) => `${r.where} ${r.zh}`));
  // generic words keep the official English: no nameEn on them
  check('no nameEn on a generic row (gems, generic bases, generic skills)', [
    ...X.D2X_GEMS.filter((g) => g.nameEn).map((g) => g.id),
    ...BASES.filter((b) => b.nameEn && b.type !== 'rune' && !(renamedBases[b.code] && !renamedBases[b.code].generic)).map((b) => b.code),
    ...allSkills.filter(([n, s]) => s.nameEn && !(renamedSkills[n] || runewordOf.has(s.name))).map(([n]) => n),
  ]);
  check(
    "a skill named by a runeword has the runeword's English name too",
    allSkills.filter(([, s]) => runewordOf.has(s.name) && s.nameEn !== runewordOf.get(s.name).nameEn).map(([n, s]) => `${n} ${s.nameEn}`),
  );
  check(
    'nameEn never reads as its official English (case, apostrophes, spaces, hyphens, "of", "the", "a", "an", a possessive \'s and the word order aside)',
    named.filter((r) => r.en && sameWords(r.nameEn, r.en)).map((r) => `${r.where} ${r.nameEn} = ${r.en}`),
  );
  // nor, for a whole name (not a word of an affix or a composed name, where "Steel" or "Fiend" is an
  // ordinary word), any other row's official English: uniques, sets, runewords, monsters, areas, NPCs
  const world = await strings('monsters', 'levels', 'npcs');
  const officialEn = new Map();
  for (const r of [...rows(uniqueJ), ...rows(setItemsJ), ...rows(setsJ)]) if (S.en[r.index]) officialEn.set(norm(S.en[r.index]), S.en[r.index]);
  for (const r of rows(runesJ)) if (r.complete && (S.en[r.Name] ?? r['*Rune Name'])) officialEn.set(norm(S.en[r.Name] ?? r['*Rune Name']), S.en[r.Name] ?? r['*Rune Name']);
  for (const v of Object.values(world.en)) if (v && v.trim().length > 3) officialEn.set(norm(v), v);
  const WORDS = new Set(['prefixes', 'suffixes', 'automagic', 'rare prefixes', 'rare suffixes', 'unique monster prefixes', 'unique monster suffixes', 'unique monster titles']);
  check('a whole name is no official English name of a unique, set, runeword, monster, area or NPC', named.filter((r) => !WORDS.has(r.group) && officialEn.has(norm(r.nameEn))).map((r) => `${r.where} ${r.nameEn} = ${officialEn.get(norm(r.nameEn))}`));
  check('nameEn is plain ASCII', named.filter((r) => !/^[\x20-\x7E]+$/.test(r.nameEn)).map((r) => `${r.where} ${r.nameEn}`));
  // Title Case: every word, and every part of a hyphenated one ("Death's-Head"), capitalised but the
  // small ones inside a name ("of", "the", "Man-at-Arms"); a name starts lowercase only where its slot
  // reads on from the base or monster name: a magic suffix with "of" (an automagic row as the
  // suffix its English is), a monster title with "the"
  const SMALL = new Set(['of', 'the', 'a', 'an', 'and', 'or', 'nor', 'in', 'on', 'at', 'to', 'for', 'from', 'with', 'by']);
  const leading = (r) => (r.group === 'suffixes' || (r.group === 'automagic' && /^of /.test(r.en)) ? 'of' : r.group === 'unique monster titles' ? 'the' : undefined);
  const titleCase = (r) =>
    r.nameEn.split(' ').every((w, i) => w.split('-').every((p, j) => /^[A-Z0-9]/.test(p) || (SMALL.has(p) && (i > 0 || j > 0 || p === leading(r)))));
  check('nameEn is in Title Case, every hyphenated part too (only a suffix starts with "of", a monster title with "the")', named.filter((r) => !titleCase(r)).map((r) => `${r.where} ${r.nameEn}`));
  // style-en.md's "about 1–4 words": five at most, where an "of the" takes two ("Mantle of the Stone
  // Ram"); a sixth makes a sentence of it
  check('nameEn is five words at most', named.filter((r) => r.nameEn.split(' ').length > 5).map((r) => `${r.where} ${r.nameEn}`));
  // the grammar of the slots (style-en.md, "Per category"): magic suffixes "of …" (magicsuffix Name,
  // "of Warding"), prefixes never (magicprefix Name, "Jagged"); automagic.txt's Name has both kinds,
  // "Fletcher's" before the base and "of the Jackal" after it, so an automagic row takes the slot its
  // own English has; rare words (rareprefix, raresuffix name) and monster name words (uniqueprefix,
  // uniquesuffix Name) one word; monster titles (uniqueappellation Name, "the Hammer") "the" and one
  // word, after the name
  const grammar = [];
  for (const r of named) {
    const g = r.group;
    const ofSuffix = /^of /.test(r.nameEn);
    if (g === 'suffixes' && !ofSuffix) grammar.push(`${r.where} ${r.nameEn}: a suffix starts with "of"`);
    if (g === 'prefixes' && ofSuffix) grammar.push(`${r.where} ${r.nameEn}: a prefix does not start with "of"`);
    if (g === 'automagic' && ofSuffix !== /^of /.test(r.en)) grammar.push(`${r.where} ${r.nameEn}: "${r.en}" is a ${ofSuffix ? 'prefix' : 'suffix'}`);
    if (['rare prefixes', 'rare suffixes', 'unique monster prefixes', 'unique monster suffixes'].includes(g) && /\s/.test(r.nameEn)) grammar.push(`${r.where} ${r.nameEn}: one word`);
    if (g === 'unique monster titles' && !/^the [A-Z]\S*$/.test(r.nameEn)) grammar.push(`${r.where} ${r.nameEn}: "the" and one word`);
  }
  check('affix and name-word grammar: suffixes "of …", prefixes not, rare and monster name words one word, titles "the …"', grammar);
  // No two rows share one: across uniques, set items, sets and runewords, and within each other group
  // (rows of one name string share theirs: affixes and rare words by name, the quest bases their unique's);
  // "Twinshade", "Twin Shade" and "Twin-Shade" are one name
  const dups = [];
  const byGroup = new Map();
  for (const r of named) {
    const k = r.nameEn.toLowerCase().replace(/[\s-]+/g, '');
    const seen = byGroup.get(r.group) ?? byGroup.set(r.group, new Map()).get(r.group);
    const prev = seen.get(k);
    if (prev && prev.en !== r.en) dups.push(`${r.where} and ${prev.where}: ${r.nameEn}`);
    else seen.set(k, r);
  }
  check('no two names alike: none across uniques, set items, sets and runewords, none inside another group', dups);
  // the glossary: every transliteration has its English form, and the names use it
  const glossary = ours('glossary');
  const glossaryEn = ours('glossary-en');
  const gBad = [];
  for (const g of glossary) {
    const e = glossaryEn.find((x) => x.new === g.new && x.en === g.en && x.official === g.official);
    if (!e?.newEn || !/^[\x20-\x7E]+$/.test(e.newEn)) gBad.push(`${g.en} ${g.new}: no ASCII newEn in glossary-en.json`);
  }
  if (glossaryEn.length !== glossary.length) gBad.push(`glossary-en.json has ${glossaryEn.length} terms, glossary.json ${glossary.length}`);
  check(`glossary-en.json gives every term of glossary.json (${glossary.length}) an English form`, gBad);
  // where our Chinese name uses a transliteration of the glossary, our English uses its English form
  const forms = glossaryEn.filter((g) => g.newEn);
  check(
    'transliterated names use the glossary: where our Chinese has its form, our English has its English form',
    named.flatMap((r) => forms.filter((g) => r.zh.includes(g.new) && !r.nameEn.includes(g.newEn)).map((g) => `${r.where} ${r.zh} ${r.nameEn}: ${g.new} is ${g.newEn}`)),
  );
  // and no English name keeps one of D2's (its people, places and powers: Horadric, Akara, Zakarum, …)
  // ("tarn" is also English, a mountain lake, free for a name of ours; Tarnhelm is still D2's)
  const blizzard = glossaryEn.flatMap((g) => g.en.split(/ \/ | \(|\)/).map((t) => t.trim()).filter((t) => t && t !== 'Tarn').map((t) => ({ t, g })));
  check(
    "no English name keeps a name of D2's the glossary replaces",
    named.flatMap((r) => blizzard.filter(({ t }) => new RegExp(`(^|[^A-Za-z])${t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}(?![a-z])`).test(r.nameEn)).map(({ t, g }) => `${r.where} ${r.nameEn}: ${t} is ${g.newEn}`)),
  );
  // Close to Blizzard's: a name a letter or two away from its row's own English, after the norm above
  // ("Haenna" for Hannah, "Pock" for Pox, "of Freezing Arrow" for of Freezing Arrows), reads as a
  // respelling of it, the English for a homophone (tools/d2-names/style-en.md, hard rule 1). Printed
  // for a look, never failed, since a short word can be that close and still be another word ("Rime"
  // for Ice). Blizzard's English of a row, `en`, is the enUS of the
  // string the d2data table names it by (uniqueitems and setitems index, sets index, runes Name,
  // magicprefix, magicsuffix and automagic Name, rareprefix and raresuffix name, monstats NameStr,
  // superuniques Name, levels LevelName, uniqueprefix, uniquesuffix and uniqueappellation Name,
  // hireling NameFirst..NameLast), in D2CE's string tables. The glossary's transliterations are taken
  // out of both first (ours from ours, D2's from D2's: "Ghiyed" for Gheed is looked at there), and
  // what is left is compared, so a name whose person is all that changed is compared too ("Weirtel's
  // Leg" for Wirt's Leg).
  const editDistance = (a, b) => {
    let prev = Array.from({ length: b.length + 1 }, (_, j) => j);
    for (let i = 1; i <= a.length; i++) {
      const cur = [i];
      for (let j = 1; j <= b.length; j++) cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
      prev = cur;
    }
    return prev[b.length];
  };
  const esc = (t) => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  // one RegExp per term, longest first ("Daikor Kahin" before "Kahin"), with its "of" or "'s" ("Lance
  // of Yaggai" and "Yagorai's Tilting Spear" are both the person's lance)
  const terms = (list) =>
    [...new Set(list)].sort((a, b) => b.length - a.length).map((t) => new RegExp(`(^|[^A-Za-z])(?:of (?:the )?)?${esc(t)}(?:['’]s)?(?![a-z])`, 'g'));
  const ourTerms = terms(forms.map((g) => g.newEn));
  const theirTerms = terms(blizzard.map(({ t }) => t));
  const strip = (s, res) => res.reduce((acc, re) => acc.replace(re, '$1'), s);
  // rows of one D2 string (an affix on several item types) are one name: listed once, with a count
  const rest = [];
  const ofString = new Map();
  for (const r of named.filter((r) => r.en)) {
    const k = `${r.group}|${r.nameEn}|${r.en}`;
    if (ofString.has(k)) ofString.get(k).n++;
    else rest.push(ofString.set(k, { r, n: 1, ours: norm(strip(r.nameEn, ourTerms)), theirs: norm(strip(r.en, theirTerms)) }).get(k));
  }
  const where = ({ r, n }) => (n > 1 ? `${r.where} (and ${n - 1} more of its string)` : r.where);
  // Where our Chinese too only swapped the transliteration for the glossary's (韦尔特的腿 for 怀特的腿,
  // quest items and bases named after a person or place), the English follows it on purpose: those
  // are counted, not listed. The official Chinese is the names files' `official` (D2CE's zhCN of the
  // same string), looked up by names file and our Chinese name: one Chinese word can stand for rows
  // of two files whose official Chinese differ (坚盾 for the monster suffix 之盾 and the rare word 盾牌),
  // and inside one file it has one.
  const officialZh = new Map();
  for (const f of fs.readdirSync(path.join(ROOT, 'tools/d2-names')).filter((f) => f.endsWith('.json') && !f.startsWith('glossary'))) {
    const file = f.replace(/\.json$/, '');
    for (const v of Object.values(ours(file))) if (v?.name && v.official) officialZh.set(`${file}|${v.name}`, v.official.trim());
  }
  const officialOf = (r) => r.files.map((f) => officialZh.get(`${f}|${r.zh}`)).find(Boolean);
  // (Chinese has no word breaks: each term is cut out wherever it stands, longest first)
  const zhTerms = (key) => [...new Set(glossary.map((g) => g[key]).filter((t) => t && t.length >= 2))].sort((a, b) => b.length - a.length);
  const zhStrip = (s, list) => list.reduce((acc, t) => acc.split(t).join(''), s);
  const [zhOurs, zhTheirs] = [zhTerms('new'), zhTerms('official')];
  const onlyTransliterated = (r) => !!officialOf(r) && zhStrip(r.zh, zhOurs) === zhStrip(officialOf(r), zhTheirs);
  const near = rest
    .filter(({ ours, theirs }) => ours && theirs.length >= 3)
    .map((x) => ({ ...x, d: editDistance(x.ours, x.theirs) }))
    // the same after the transliterations: only the person or place changed (the same before is a
    // failure above)
    .filter(({ r, d }) => d <= 2 && (d > 0 || norm(r.nameEn) !== norm(r.en)));
  const byDesign = near.filter(({ r, d }) => d === 0 && onlyTransliterated(r));
  warn(
    `nameEn within edit distance 2 of its row's official English (case, "the", apostrophes, spaces and hyphens aside), the glossary's transliterations taken out of both (${byDesign.length} more, only the transliteration changed as in our Chinese, not listed)`,
    near.filter((x) => !byDesign.includes(x)).map((x) => `${where(x)} ${x.r.nameEn} ~ ${x.r.en} (${x.d})`),
  );
  // The glossary's English forms against Blizzard's own: a transliteration a letter or two from
  // Blizzard's name is a respelling of it (style-en.md, hard rules 1 and 5), which the comparison
  // above cannot see, the transliterations being taken out of both there. Printed for a look: a short
  // name can be that close and still read as another.
  warn(
    "a glossary English form (glossary-en.json newEn) within edit distance 2 of Blizzard's name (case, \"the\", apostrophes, spaces and hyphens aside)",
    blizzard.filter(({ t, g }) => editDistance(norm(g.newEn), norm(t)) <= 2).map(({ t, g }) => `${g.newEn} ~ ${t} (${editDistance(norm(g.newEn), norm(t))})`),
  );
  // (Blizzard's whole name with a word added, "Bitter Rain" for Rain, is not listed: it keeps what a
  // veteran knows the row by and changes more than a respelling; style-en.md, hard rules 1 and 2.)
  // A name word that is a whole name of Blizzard's carries that name into ours: "the Lacerator" was a
  // monster title and Lacerator is a unique throwing axe (uniqueitems index Lacerator). The affixes,
  // rare words and monster name words (magicprefix, magicsuffix, automagic Name; rareprefix,
  // raresuffix name; uniqueprefix, uniquesuffix, uniqueappellation Name), their slot's "of" or "the"
  // aside, against the official English of every unique, set item, set, runeword, monster, area and
  // NPC above. Printed for a look: style-en.md only prefers another word, an ordinary one can be a
  // name too.
  warn(
    'a name word (affix, rare word, monster name word) is the whole official English of a unique, set, runeword, monster, area or NPC',
    rest
      .filter(({ r }) => WORDS.has(r.group) && officialEn.has(norm(r.nameEn.replace(/^(of|the) /, ''))))
      .map((x) => `${where(x)} ${x.r.nameEn} = ${officialEn.get(norm(x.r.nameEn.replace(/^(of|the) /, '')))}`),
  );
  // Hirelings: the Rogue Scouts' names are hireling.txt's NameFirst..NameLast, merc01 to merc41 (D2Game
  // SUnitNpc.cpp:68-76, SUNITNPC_InitializeHirelingRoster, names each slot of the roster
  // wNameFirst + i up to wNameLast): one pool, a name shown beside the others' when hiring.
  // style-en.md keeps each at least three letters (edit distance 3) from Blizzard's name for any
  // hireling and from our other hirelings', after the same norm: a name two letters from another
  // reads as that one ("Hrimna" and Oriana)
  const hirelings = named.filter((r) => r.group === 'hireling names');
  const close = [];
  for (const [i, r] of hirelings.entries()) {
    for (const o of hirelings) {
      if (o.en && editDistance(norm(r.nameEn), norm(o.en)) < 3) close.push(`${r.where} ${r.nameEn} ~ ${o.en} (${o === r ? "its own, D2's" : `D2's ${o.where}`})`);
    }
    for (const o of hirelings.slice(i + 1)) if (editDistance(norm(r.nameEn), norm(o.nameEn)) < 3) close.push(`${r.where} ${r.nameEn} ~ ${o.where} ${o.nameEn}`);
  }
  check(`hireling names (${hirelings.length}) are three letters or more from every hireling's official name and from each other`, close);
  // ...and the pool (the same NameFirst..NameLast strings) reads as many names, not one name with its
  // start changed: no more than two share their last three letters (style-en.md; seven of them once
  // ended in "-nne")
  const endings = Map.groupBy(hirelings, (r) => norm(r.nameEn).slice(-3));
  check(
    'no more than two hireling names share an ending (their last three letters)',
    [...endings].filter(([, l]) => l.length > 2).map(([e, l]) => `-${e}: ${l.map((r) => r.nameEn).join(', ')}`),
  );
}

