section('Characters: charstats in whole points, the expansion columns');
{
  const { pal, sor } = X.D2X_CLASSES;
  check(`Paladin: ${pal.lifePerLvl} life a level, ${pal.lifePerVit} a point of vitality (2 and 3)`, pal.lifePerLvl === 2 && pal.lifePerVit === 3 ? [] : 'differs');
  check(`Sorceress: ${sor.manaPerEne} mana a point of energy (2)`, sor.manaPerEne === 2 ? [] : 'differs');
  check('to-hit factor Paladin +20, Sorceress −15; block factor 30 and 20', pal.toHitFactor === 20 && sor.toHitFactor === -15 && pal.blockFactor === 30 && sor.blockFactor === 20 ? [] : 'differs');
  const rp = X.D2X_DIFFICULTIES.map((d) => d.resistPenalty);
  check(`resist penalty ${rp.join(' / ')} (ResistPenalty, not the classic column)`, same(rp, [0, -40, -100]) ? [] : 'differs');
  check(`item ratios: ${X.D2X_ITEM_RATIO.length} Version 1 rows (uber × class specific)`, X.D2X_ITEM_RATIO.length === 4 ? [] : 'not 4');
  check(`hirelings: ${X.D2X_HIRELINGS.length} Act 1 rogues, fire and cold in three difficulties (Version 100)`, X.D2X_HIRELINGS.length === 6 && X.D2X_HIRELINGS.every((h) => h.cls === 'ama') ? [] : 'differs');
}

// ───────────────────────── monsters ─────────────────────────
section('Areas and monsters: area levels, monlvl percentages');
{
  const moor = X.D2X_AREAS.find((a) => a.id === 2);
  check(`Blood Moor: area levels ${moor.lvl.join(' / ')} (MonLvlEx; the classic MonLvl is 1 / 26 / 51)`, same(moor.lvl, [1, 36, 67]) ? [] : 'differs');
  check(`monlvl: level 1 hell life ${X.D2X_MONLVL[1].hp[2]} (L-HP(H) 1107; the classic HP(H) is 830)`, X.D2X_MONLVL[1].hp[2] === 1107 ? [] : 'differs');
  // DATATBLS_ApplyRatio (D2Common MonsterTbls.cpp:932-960): a 32-bit product where it fits, else
  // the division first, else 64 bits; C's division truncates
  const applyRatio = (value, mul, div) => {
    if (!div) return 0;
    if (value <= 0x100000) {
      if (mul <= 0x10000) return Math.trunc(Math.imul(mul, value) / div);
      if (div <= mul >> 4) return Math.imul(value, Math.trunc(mul / div));
    } else if (div <= value >> 4) return Math.imul(mul, Math.trunc(value / div));
    return Number((BigInt(mul) * BigInt(value)) / BigInt(div)) | 0;
  };
  // life = ApplyRatio(monlvl HP of the level and difficulty, + 3 for the expansion's L- columns, minHP or maxHP, 100) (562-731)
  const f = X.D2X_MONSTERS.fallen1;
  const raw = rows(monJ).find((m) => m.Id === 'fallen1');
  const lvlRow = (l) => rows(lvlJ).find((r) => r.Level === l);
  const life = (l) => f.diff[0].hp.map((pct) => applyRatio(X.D2X_MONLVL[l].hp[0], pct, 100));
  const lifeRaw = (l) => [raw.minHP, raw.maxHP].map((pct) => applyRatio(lvlRow(l)['L-HP'], pct, 100));
  const bad = [];
  // its own level, as a champion (+2) and a unique (+3), and two more
  for (const l of [1, 3, 4, 20, 85]) if (!same(life(l), lifeRaw(l))) bad.push(`level ${l}: ${life(l)} from the data, ${lifeRaw(l)} from the tables`);
  if (!same(life(1), [1, 4])) bad.push(`level 1: ${life(1)}; a Blood Moor fallen has 1–4`);
  check(`fallen1 normal life, ApplyRatio(L-HP, minHP/maxHP %, 100): ${life(1).join('–')} at its level 1, ${life(4).join('–')} at 4, ${life(20).join('–')} at 20`, bad);
  check(`fallen1 keeps percentages (minHP ${f.diff[0].hp[0]}, maxHP ${f.diff[0].hp[1]}), not points`, f.diff[0].level === 1 && same(f.diff[0].hp, [raw.minHP, raw.maxHP]) ? [] : 'differs');
}

// ───────────────────────── treasure ─────────────────────────
section("Drops: Andariel's and the Countess' items a kill, against tcprecalc (2.7)");
{
  const P = R27.tcprecalc;
  const RUNS = 10000;
  // Andariel names Andarielq in all her columns; the Countess drops her superunique classes
  const names = [...X.D2X_MONSTERS.andariel.diff.map((d) => d.tc.regular), ...X.D2X_SUPERUNIQUES.find((s) => s.key === 'The Countess').tc];
  for (const n of names) {
    const mine = leaves(n, (x) => TCS[x]);
    const d = maxDiff(mine, leavesPre(n, P));
    // the drop rules played out on the generated data, seeded: z = (simulated − expected) / standard error
    const rnd = seeded(0xd2 + n.length);
    const got = new Map();
    for (let i = 0; i < RUNS; i++) {
      const drops = [];
      simulate(n, TCS, rnd, drops);
      for (const x of drops) got.set(x, (got.get(x) ?? 0) + 1);
    }
    let z = 0;
    for (const [k, v] of mine) if (v >= 0.01) z = Math.max(z, Math.abs((got.get(k) ?? 0) / RUNS - v) / Math.sqrt(v / RUNS));
    const total = [...mine.values()].reduce((s, x) => s + x, 0);
    check(`${n}: ${mine.size} items, ${total.toFixed(4)} a kill; off tcprecalc by ${d.toExponential(1)} at most, simulated |z| ≤ ${z.toFixed(2)}`, d > 1e-9 || z > 4.5 ? `difference ${d}, z ${z}` : []);
  }
  const auto = Object.entries(TCS).filter(([, t]) => t.auto && t.items.length);
  const share = (t) => new Map(t.items.map((e) => [e.item, e.prob / t.items.reduce((s, x) => s + x.prob, 0)]));
  check(`the ${auto.length} automatic classes (weapN, armoN, …) match tcprecalc item by item`, auto.filter(([n, t]) => !P[n] || maxDiff(share(t), new Map(Object.entries(P[n].counts))) > 1e-12).map(([n]) => n));
}

