section('Properties');
{
  const mapped = new Set(PROP_CODES);
  const bad = [];
  const used = new Set();
  for (const [where, ps] of allProps) {
    for (const p of ps) {
      used.add(p.c);
      if (p.c !== p.c.toLowerCase() || p.c.startsWith('*')) bad.push(`${where}: code ${p.c}`);
      else if (!mapped.has(p.c) && !KNOWN_UNMAPPED[p.c]) bad.push(`${where}: ${p.c} is neither read by props.ts nor in KNOWN_UNMAPPED`);
      if (SKILL_PROPS.has(p.c) && !X.D2X_SKILLS[p.p] && !X.D2X_SKILL_REFS[p.p]) bad.push(`${where}: ${p.c} names ${p.p}, which the skill data lacks`);
    }
  }
  check(`every property code (${used.size}) is read by src/items/props.ts or in KNOWN_UNMAPPED, lower case, its skill in the data`, bad);
  check('KNOWN_UNMAPPED lists no code props.ts reads', Object.keys(KNOWN_UNMAPPED).filter((c) => mapped.has(c)));
  // what a stat adds to an item's price (D2Common Items.cpp:1841-1957): ItemStatCost Multiply / Add / Encode
  const isc = by(R27.itemstatcost, 'Stat');
  const priced = [];
  for (const [stat, d] of Object.entries(X.D2X_STAT_DESC)) {
    const r = isc.get(stat);
    if (!r) continue;
    mismatch(priced, stat, 'cost', r.Multiply || r.Add ? [r.Multiply ?? 0, r.Add ?? 0] : undefined, d.cost);
    mismatch(priced, stat, 'enc', opt(r.Encode), d.enc);
  }
  check('stat prices: ItemStatCost Multiply, Add and Encode as 2.7 has them', priced);
}

// ───────────────────────── skills ─────────────────────────
section('Skills: the two trees, HitShift, manashift, frames');
{
  for (const cls of ['pal', 'sor']) {
    const want = rows(skillsJ).filter((s) => s.charclass === cls && s.InGame).map((s) => s.skill);
    const got = skills.filter((s) => s.cls === cls);
    const missing = want.filter((n) => !X.D2X_SKILLS[n]?.name || !X.D2X_SKILLS[n]?.desc);
    const label = `${cls === 'pal' ? 'Paladin' : 'Sorceress'}: ${got.length} skills, all ${want.length} of the tree, each with a name and a description`;
    check(label, want.length === 30 && got.length === 30 ? missing : [`${want.length} in the table, ${got.length} in the data`, ...missing]);
  }
  // 2.7's bands × 2^HitShift / 256 give points, mana × 2^manashift / 256, lengths frames / 25
  const old = new Map(rows(R27.skills).filter((s) => s.skill).map((s) => [s.skill, s]));
  const bad = [];
  for (const [n, s] of Object.entries(X.D2X_SKILLS)) {
    const r = old.get(n);
    const hs = (v) => ((v ?? 0) * 2 ** (r.HitShift ?? 0)) / 256;
    const band = (base, per) => [base, ...per].map((c) => r[c]);
    const lev = (p) => [1, 2, 3, 4, 5].map((i) => `${p}${i}`);
    if (s.elem?.min) mismatch(bad, n, 'elem.min', band('EMin', lev('EMinLev')).map(hs), s.elem.min);
    if (s.elem?.max) mismatch(bad, n, 'elem.max', band('EMax', lev('EMaxLev')).map(hs), s.elem.max);
    if (s.phys) mismatch(bad, n, 'phys.min', band('MinDam', lev('MinLevDam')).map(hs), s.phys.min);
    if (s.phys) mismatch(bad, n, 'phys.max', band('MaxDam', lev('MaxLevDam')).map(hs), s.phys.max);
    if (s.elem?.len) mismatch(bad, n, 'elem.len', band('ELen', ['ELevLen1', 'ELevLen2', 'ELevLen3']).map((v) => (v ?? 0) / 25), s.elem.len);
    if (s.mana) mismatch(bad, n, 'mana', [r.mana ?? 0, r.lvlmana ?? 0].map((v) => (v * 2 ** (r.manashift ?? 0)) / 256), [s.mana.base, s.mana.perLvl]);
  }
  check(`every skill (${skills.length}): damage with HitShift, mana with manashift, lengths in seconds, as 2.7 has them`, bad);
  const fb = X.D2X_SKILLS['Fire Bolt'];
  check(`Fire Bolt level 1: ${fb.elem.min[0]}–${fb.elem.max[0]} fire damage for ${fb.mana.base} mana (D2: 3–6 for 2.5)`, fb.elem.min[0] === 3 && fb.elem.max[0] === 6 && fb.mana.base === 2.5 ? [] : 'differs');
  const nova = X.D2X_SKILLS['Frost Nova'];
  check(`Frost Nova level 1 chills for ${nova.elem.len[0]} s (200 frames)`, nova.elem.len[0] === 8 ? [] : 'differs');
}

console.log(`\n${passed} checks passed, ${failed} failed${warned ? `, ${warned} name${warned > 1 ? 's' : ''} to look at` : ''}`);
if (failed) process.exitCode = 1;
